# -*- coding: utf-8 -*-
from gen2 import *

m1 = M(('Среднее и медиана: выброс', 'Mean and median: an outlier'),
 [('r', 'x', 'Значение десятого человека, тыс. сом', 'Value of the tenth person, thousand som', 10, 500, 10, 30)],
 [('Среднее', 'Mean'), ('Медиана', 'Median'), ('Мода', 'Mode')],
 'Среднее — сумма, делённая на число значений; медиана — значение посередине упорядоченного ряда. Одно экстремальное значение сильно сдвигает среднее, но почти не меняет медиану. Данные условные.', 'The mean is the sum divided by the count; the median is the middle value of the ordered list. One extreme value strongly shifts the mean but hardly changes the median. The data are illustrative.', ('Месячные доходы 10 человек (условно)', 'Monthly incomes of 10 people (illustrative)'),
 r'''const d=[20,22,24,25,25,26,28,30,32,v.x].sort((a,b)=>a-b),mean=d.reduce((a,b)=>a+b,0)/d.length,med=(d[4]+d[5])/2;const mx=Math.max(520,...d)*1.05,X=t=>50+t/mx*500;let g=L(50,150,550,150,COL.ink,2);for(let t=0;t<=500;t+=100)g+=L(X(t),146,X(t),154,COL.ink,1.5)+TX(X(t),172,String(t),COL.mut,11);d.forEach((t,i)=>{g+=C(X(t),130-((i>0&&d[i-1]===t)?16:0),7,t===v.x&&t>32?COL.a:COL.b)});g+=L(X(mean),60,X(mean),150,COL.a,3)+TX(X(mean),52,U("среднее ","mean ")+fnum(mean,1),COL.a,13,"middle",700)+L(X(med),85,X(med),150,COL.c,3,0)+TX(X(med),100,U("медиана ","median ")+fnum(med,1),COL.c,13,"middle",700);
 return {svg:g,st:[fnum(mean,1),fnum(med,1),"25"],fb:mean-med>8?U("Выброс сдвинул среднее далеко вправо — медиана описывает «типичный» доход лучше.","The outlier pulled the mean far to the right — the median describes the “typical” income better."):U("Без выбросов среднее и медиана близки.","Without outliers the mean and the median are close.")}''', '0 0 600 190')

m2 = M(('Разброс: размах и отклонение', 'Spread: range and deviation'),
 [('r', 's', 'Во сколько раз шире разброс', 'How many times wider the spread', 0.5, 3, 0.25, 1)],
 [('Среднее', 'Mean'), ('Размах (макс − мин)', 'Range (max − min)'), ('Станд. отклонение σ', 'Standard deviation σ')],
 'Два ряда могут иметь одно среднее и разный разброс. Стандартное отклонение σ = √(среднее значение (x − среднее)²) — типичное удаление значений от среднего.', 'Two lists may have the same mean and a different spread. The standard deviation σ = √(mean of (x − mean)²) is the typical distance of values from the mean.', ('Те же центр и разный разброс', 'The same centre and a different spread'),
 r'''const base=[-3,-2,-1,-1,0,0,1,1,2,3],d=base.map(t=>50+t*v.s*3),mean=d.reduce((a,b)=>a+b,0)/d.length,sd=Math.sqrt(d.reduce((a,t)=>a+(t-mean)*(t-mean),0)/d.length);const X=t=>50+(t-20)/60*500;let g=L(50,130,550,130,COL.ink,2);for(let t=20;t<=80;t+=10)g+=L(X(t),126,X(t),134,COL.ink,1.5)+TX(X(t),152,String(t),COL.mut,11);d.forEach((t,i)=>g+=C(X(t),110-(i%3)*0,7,COL.b));g+=L(X(mean),50,X(mean),130,COL.a,3)+R(X(mean-sd),60,X(mean+sd)-X(mean-sd),14,COL.a+"55",COL.a,1.5,2)+TX(X(mean),48,"±σ",COL.a,13,"middle",700);
 return {svg:g,st:[fnum(mean,1),fnum(Math.max(...d)-Math.min(...d),1),fnum(sd,2)],fb:U("Среднее не меняется, а σ растёт вместе с разбросом.","The mean stays the same while σ grows with the spread.")}''', '0 0 600 170')

m3 = M(('Гистограмма и квартили', 'A histogram and quartiles'),
 [('s', 'k', 'Форма данных', 'Shape of the data', ['симметричные', 'с «хвостом»'], ['symmetric', 'with a “tail”'], 0), ('r', 'b', 'Число столбцов', 'Number of bins', 3, 15, 1, 8)],
 [('Среднее / медиана', 'Mean / median'), ('Квартили Q₁ и Q₃', 'Quartiles Q₁ and Q₃'), ('Межквартильный размах', 'Interquartile range')],
 'Гистограмма показывает форму данных: симметричную или с «хвостом» (тогда среднее оказывается правее медианы). Квартили делят ряд на четыре равные части. Данные — псевдослучайные, учебные.', 'A histogram shows the shape of the data: symmetric or with a “tail” (then the mean is to the right of the median). Quartiles split the list into four equal parts. The data are pseudo-random, for teaching.', ('Гистограмма 120 значений', 'A histogram of 120 values'),
 r'''let s=777;const rnd=()=>{s=(s+0x6D2B79F5)|0;let t=Math.imul(s^(s>>>15),1|s);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296};const d=[];for(let i=0;i<120;i++){if(v.k===0){const u1=rnd()+1e-9,u2=rnd();d.push(50+10*Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2))}else d.push(30+(-Math.log(rnd()+1e-9))*14)}d.sort((a,b)=>a-b);
 const qt=p=>{const i=(d.length-1)*p,lo=Math.floor(i);return d[lo]+(d[Math.min(lo+1,d.length-1)]-d[lo])*(i-lo)};const mean=d.reduce((a,b)=>a+b,0)/d.length,med=qt(0.5),q1=qt(0.25),q3=qt(0.75);
 const mn=Math.floor(d[0]),mxv=Math.ceil(d[d.length-1]),B=v.b,w=(mxv-mn)/B,cnt=new Array(B).fill(0);d.forEach(t=>{cnt[Math.min(B-1,Math.floor((t-mn)/w))]++});const cm=Math.max(...cnt),X=t=>50+(t-mn)/(mxv-mn)*500;let g=L(50,190,550,190,COL.ink,2);cnt.forEach((c,i)=>{const h=150*c/cm;g+=R(50+i*500/B,190-h,500/B-2,h,COL.a,COL.ink,1,1)});g+=L(X(mean),30,X(mean),190,COL.b,3)+L(X(med),30,X(med),190,COL.c,3,0)+TX(X(mean),24,U("ср.","mean"),COL.b,12,"middle",700)+TX(X(med)-18,24,U("мед.","med."),COL.c,12,"middle",700);
 return {svg:g,st:[fnum(mean,1)+" / "+fnum(med,1),fnum(q1,1)+" и "+fnum(q3,1),fnum(q3-q1,1)],fb:v.k===1?U("«Хвост» вправо: среднее правее медианы.","A right tail: the mean is right of the median."):U("Симметричные данные: среднее и медиана почти совпадают.","Symmetric data: the mean and median nearly coincide.")}''', '0 0 600 215')

chapter('74', '74-statistics.html', 'X', ('Статистика: среднее, медиана, разброс', 'Statistics: mean, median, spread'),
 ('Как описывать данные одним-двумя числами, когда им можно верить и как читать диаграммы.', 'How to describe data with one or two numbers, when they can be trusted and how to read charts.'),
 ('В кафе в посёлке сказали: «Средняя зарплата у нас — 80 тысяч сомов». Человек из десяти сотрудников получает 30 тысяч. Как такое возможно?', 'In a village café they said: “The average salary here is 80 thousand som.” A typical one of ten employees receives 30 thousand. How is that possible?'),
 ('Разгадка: влияние одного большого значения', 'The answer: the effect of one large value'),
 ('Если девять человек получают по 30 тысяч, а владелец 530, то среднее — (9·30 + 530)/10 = 80 тысяч, а медиана — 30. Среднее легко «тянут» выбросы. Поэтому для доходов, цен на жильё, времени ожидания часто приводят медиану и разброс, а не только среднее. (Цифры придуманы для задачи.)', 'If nine people earn 30 thousand and the owner 530, the mean is (9·30 + 530)/10 = 80 thousand while the median is 30. The mean is easily dragged by outliers. That is why for incomes, housing prices, waiting times the median and the spread are often given and not only the mean. (The figures are invented for the exercise.)'),
 [S('centre', 'Центр данных', 'The centre of the data', ('<strong>Среднее</strong> x̄ = (x₁ + … + xₙ)/n. <strong>Медиана</strong> — середина упорядоченного ряда (при чётном n — полусумма двух средних). <strong>Мода</strong> — самое частое значение. Среднее чувствительно к выбросам, медиана — устойчива.', 'The <strong>mean</strong> x̄ = (x₁ + … + xₙ)/n. The <strong>median</strong> is the middle of the ordered list (for even n the half-sum of the two middle values). The <strong>mode</strong> is the most frequent value. The mean is sensitive to outliers, the median is robust.'),
    ('x̄ = Σxᵢ / n', '', 'x̄ = Σxᵢ / n'), m1),
  S('spread', 'Разброс', 'The spread', ('<strong>Размах</strong> = максимум − минимум. <strong>Стандартное отклонение</strong> σ = √(Σ(xᵢ − x̄)²/n) — типичное расстояние до среднего. Два ряда с одним средним могут сильно различаться: у 49, 50, 51 и у 10, 50, 90 среднее 50, но σ ≈ 0,8 и ≈ 32.', 'The <strong>range</strong> = maximum − minimum. The <strong>standard deviation</strong> σ = √(Σ(xᵢ − x̄)²/n) is the typical distance to the mean. Two lists with the same mean may differ greatly: for 49, 50, 51 and 10, 50, 90 the mean is 50, but σ ≈ 0.8 and ≈ 32.'),
    ('σ = √(Σ(xᵢ − x̄)²/n)', '', 'σ = √(Σ(xᵢ − x̄)²/n)'), m2),
  S('chart', 'Диаграммы и честность данных', 'Charts and honest data', ('<strong>Гистограмма</strong> показывает форму; <strong>квартили</strong> Q₁, Q₂ (медиана), Q₃ делят ряд на четыре части. Чтобы не обмануться: смотрите масштаб осей, размер выборки, откуда взяты данные и не путайте корреляцию («связаны») с причиной («вызывает»).', 'A <strong>histogram</strong> shows the shape; the <strong>quartiles</strong> Q₁, Q₂ (the median), Q₃ split the list into four parts. To avoid being fooled: look at the axis scales, the sample size, where the data come from, and do not confuse correlation (“related”) with cause (“causes”).'),
    ('IQR = Q₃ − Q₁', '', 'IQR = Q₃ − Q₁'), m3)],
 [TK(('Среднее', 'Mean'), ('Среднее чисел 4, 6, 8, 10, 12.', 'The mean of 4, 6, 8, 10, 12.'), '', '40/5 = 8.', '8.'),
  TK(('Медиана', 'Median'), ('Медиана 3, 9, 5, 7.', 'The median of 3, 9, 5, 7.'), 'Порядок: 3, 5, 7, 9', '(5 + 7)/2 = 6.', '6.'),
  TK(('Выброс', 'Outlier'), ('Как изменится среднее и медиана, если в ряд 1, 2, 3, 4, 5 добавить 100?', 'How do the mean and median change if 100 is added to 1, 2, 3, 4, 5?'), '', 'Среднее 115/6 ≈ 19,2; медиана 3,5.', ('Среднее ≈ 19,2, медиана 3,5.', 'The mean ≈ 19.2, median 3.5.')),
  TK(('Отклонение', 'Deviation'), ('σ для ряда 2, 4, 6.', 'σ for 2, 4, 6.'), 'x̄ = 4', '√((4 + 0 + 4)/3) = √(8/3) ≈ 1,63.', '≈ 1,63.'),
  TK(('Мода', 'Mode'), ('Мода ряда 2, 3, 3, 5, 3, 7.', 'The mode of 2, 3, 3, 5, 3, 7.'), '', '3.', '3.')],
 [Q('Среднее 2, 4, 6', 'The mean of 2, 4, 6', '4', '6', '3', ('12/3.', '12/3.')),
  Q('Медиана 1, 3, 100', 'The median of 1, 3, 100', '3', '34,7', '100', ('Середина.', 'The middle.')),
  Q('К выбросам чувствительнее', 'More sensitive to outliers is the', ('среднее', 'mean'), ('медиана', 'median'), ('мода', 'mode'), ('Среднее «тянет».', 'The mean is “dragged”.')),
  Q('Размах = ', 'Range = ', ('макс − мин', 'max − min'), ('макс + мин', 'max + min'), ('среднее − мода', 'mean − mode'), ('Определение.', 'Definition.')),
  Q('σ описывает', 'σ describes', ('разброс', 'spread'), ('центр', 'the centre'), ('количество', 'the count'), ('Типичное удаление.', 'Typical distance.')),
  Q('Корреляция означает', 'Correlation means', ('связь величин', 'a relation of quantities'), ('причину', 'a cause'), ('ошибку', 'an error'), ('Не обязательно причина.', 'Not necessarily a cause.')),
  Q('Q₂ — это', 'Q₂ is the', ('медиана', 'median'), ('среднее', 'mean'), ('размах', 'range'), ('Второй квартиль.', 'The second quartile.')),
  Q('Чтобы не обмануться диаграммой, проверьте', 'To avoid being fooled by a chart, check', ('масштаб осей и выборку', 'the axis scales and the sample'), ('цвет', 'the colour'), ('шрифт', 'the font'), ('Важны масштаб и данные.', 'Scales and data matter.'))],
 src=[('Wikipedia: Median', 'https://en.wikipedia.org/wiki/Median'), ('Wikipedia: Standard deviation', 'https://en.wikipedia.org/wiki/Standard_deviation'), ('Wikipedia: Histogram', 'https://en.wikipedia.org/wiki/Histogram'), ('OpenStax: Introductory Statistics 2e', 'https://openstax.org/details/books/introductory-statistics-2e')],
 note=('Кафе, доходы и данные в моделях придуманы; данные гистограммы — псевдослучайные.', 'The café, incomes and data in the models are invented; the histogram data are pseudo-random.'))
